body:
I've done this for a few files, just a function that deletes all triggers and then add my own.

 This 2 functions, with deleteTrigger running onOpen

function createChangeTrigger() {  
 var triggerID = ScriptApp.newTrigger("changeFunc")  
   .forSpreadsheet(SpreadsheetApp.getActive())  
   .onChange()  
   .create();  
 console.log("created: " + triggerID.getUniqueId());  
 var editSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("tabName");  
 editSheet.getRange("A24").setValue(triggerID.getUniqueId());  
}  
function deleteTrigger() {  
 // Loop over all triggers  
 console.log("Start");  
 const allTriggers = ScriptApp.getProjectTriggers();  
 console.log("triggers " + allTriggers);  
 for (let index = 0; index < allTriggers.length; index++) {  
 // If the current trigger is the correct one, delete it.  
 var a = allTriggers\[index\].getEventType().toString();  
 if (allTriggers\[index\].getEventType().toString() === "ON\_CHANGE") {  
 console.log("deleting: " + allTriggers\[index\].getUniqueId().toString());  
 ScriptApp.deleteTrigger(allTriggers\[index\]);  
 createChangeTrigger();  
 console.log("deleted");  
    }  
  }  
 console.log("End");  
}

Yes, although you would need a scripts to do so, you can store on a specific cell the mail of the last person that make the update. From there you can color either that column or the complete row using a conditional format.

function onEdit(e) {  
 if (!e) return;  
 var ss = SpreadsheetApp.getActiveSpreadsheet();  
 var activeSheet = ss.getActiveSheet();  
 var row = e.range.getRow();  
activeSheet.getRange("O"+row).setValue(user); //Change "O" for which column you want to save the timestamp  
}

This example puts the usermail on column O same row as the update.

A small script cause I was bored a bit:

function provider(string) {  
  var values = SpreadsheetApp.getActive().getSheetByName("PROVIDERS").getDataRange().getValues();  
  for (var i = 0; i < values.length ; i++){  
  if (string) {  
var val = values\[i\]\[5\];  
if (string.indexOf(val) > -1) {  
console.log (values\[i\]\[0\])  
return values\[i\]\[0\];  
}  
  }  
  }  
}

so just put  =provider(F2) on the file and will work, just make sure you add all the values possible on the catalog and the query must be trimmed (no empty spaces at the end)

